// 更多产品统一承载床单、床笠、夹棉床笠与旅行睡袋，保持原产品ID与生成规则。
// UI 结构与 dist/blanket-variants.js 完全一致，复用同一套子菜单浮层与定位逻辑。
const sleepbagProductVariants=[
  {id:'travel',name:'旅行睡袋',hint:'无填充薄布内衬 · 半长侧入口 · 隐形脚端拉链 · 下片背面枕袋',spec:'旅行睡袋类别：1件酒店隔脏薄布内衬，双层是上下两片等宽布、不是夹棉。两长边仅脚侧下半段缝合，中段终止，头侧上半段自由敞开。脚端短边隐形拉链，链齿藏布缝。下片头端背面接等宽约40～50厘米枕袋，袋口朝脚端，1只素色枕芯放下片下面。上片头侧可自由翻回露真实反面；下片留床面。按产品规格铺在床垫上方，不包侧墙，不做床笠，无填充、绗缝、帽兜或整圈拉链。'}
];
function currentSleepbagVariant(){return sleepbagProductVariants.find(v=>v.id===state.sleepbagVariant)||sleepbagProductVariants[0]}
function sleepbagSpecification(){return currentSleepbagVariant().spec}
const sleepbagVariantPanel=document.createElement('section');sleepbagVariantPanel.id='sleepbagVariantPanel';sleepbagVariantPanel.className='set-variant-flyout quilt-variant-flyout sleepbag-variant-flyout';sleepbagVariantPanel.hidden=true;sleepbagVariantPanel.setAttribute('aria-labelledby','sleepbagVariantTitle');
sleepbagVariantPanel.innerHTML='<div class="set-variant-heading"><div><h2 id="sleepbagVariantTitle">更多产品</h2><p>选择床单、床笠或旅行睡袋</p></div><button type="button" class="set-variant-close" aria-label="收起更多产品分类">×</button></div><div class="set-variant-options"><h3>更多家纺品种</h3><div class="set-variant-grid" role="group" aria-label="更多产品品种"></div></div><div class="set-variant-footer"><span id="sleepbagVariantSelected"></span><button type="button" class="set-variant-done">完成选择</button></div>';
document.body.append(sleepbagVariantPanel);
function renderSleepbagVariantControl(){const trigger=document.querySelector('[data-product="sleepbag"]');if(trigger){trigger.classList.add('has-sleepbag-variants');trigger.setAttribute('aria-expanded',String(!sleepbagVariantPanel.hidden));trigger.setAttribute('aria-controls','sleepbagVariantPanel');trigger.title=currentSleepbagVariant().name+' · 点击展开更多产品';renderChosenProductLabel(trigger,'更多产品',state.lastMoreProduct==='sheet'?currentSheetProductVariant().name:currentSleepbagVariant().name);}if(state.product==='sleepbag'){$('partsHint').textContent='1 条'+currentSleepbagVariant().name+' · '+currentSleepbagVariant().hint;document.querySelector('.group-angles .group-purpose').textContent=currentSleepbagVariant().name+'构图 · 可多选 · AI 示例';}sleepbagVariantPanel.querySelector('#sleepbagVariantSelected').textContent='已选：'+(state.lastMoreProduct==='sheet'?currentSheetProductVariant().name:currentSleepbagVariant().name);}
function closeSleepbagVariants(returnFocus=false){sleepbagVariantPanel.hidden=true;renderSleepbagVariantControl();if(returnFocus)document.querySelector('[data-product="sleepbag"]')?.focus()}
function placeSleepbagVariants(){placeProductSubmenu(sleepbagVariantPanel,document.querySelector('[data-product="sleepbag"]'),640,440);}
function selectSleepbagVariant(id){if(!state.busy)state.product='sleepbag';if(state.busy||!['sleepbag','sheet'].includes(state.product)||!sleepbagProductVariants.some(v=>v.id===id))return;(state.productVariantChoices??={}).sleepbag=true;state.lastMoreProduct='sleepbag';state.sleepbagVariant=id;if(state.fabricMode!=='selected'&&state.textureSource!=='upload'){state.fabric='cotton';updateFabric();}sleepbagVariantPanel.querySelectorAll('[data-sleepbag-variant]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.sleepbagVariant===id)));if(typeof renderOptions==='function')renderOptions();renderSleepbagVariantControl();renderSelections();if(typeof closeSleepbagVariants==='function')closeSleepbagVariants(true);}
function openSleepbagVariants(){if(state.busy||!['sleepbag','sheet'].includes(state.product))return;const grid=sleepbagVariantPanel.querySelector('.set-variant-grid');grid.replaceChildren();for(const item of sheetProductVariants){const b=document.createElement('button');b.type='button';b.className='set-variant-option illustrated-variant-option';b.dataset.moreSheetVariant=item.id;b.setAttribute('aria-pressed',String(state.lastMoreProduct==='sheet'&&state.sheetVariant===item.id));b.innerHTML='<span class="product-variant-preview" style="background-image:url(/assets/sheet-'+item.id+'-angles-v3-framed.png)"></span><strong>'+item.name+'</strong><small>'+item.hint+'</small>';b.onclick=()=>{if(state.busy)return;state.product='sheet';if(state.moreEntryCounts)state.setCounts={...state.moreEntryCounts};state.lastMoreProduct='sheet';(state.productVariantChoices??={}).sleepbag=true;state.sheetVariant=item.id;renderOptions();selectSheetProductVariant(item.id);closeSleepbagVariants(true);};grid.append(b);}for(const item of sleepbagProductVariants){const b=document.createElement('button');b.type='button';b.className='set-variant-option sleepbag-variant-option';b.dataset.sleepbagVariant=item.id;b.setAttribute('aria-pressed',String(state.lastMoreProduct!=='sheet'&&currentSleepbagVariant().id===item.id));const picture=document.createElement('span');picture.className='sleepbag-variant-preview sleepbag-variant-preview-'+item.id;picture.setAttribute('role','img');picture.setAttribute('aria-label',item.name+'AI 结构示例');const name=document.createElement('strong');name.textContent=item.name;const hint=document.createElement('small');hint.textContent=item.hint;b.append(picture,name,hint);b.addEventListener('click',()=>selectSleepbagVariant(item.id));grid.append(b)}sleepbagVariantPanel.hidden=false;placeSleepbagVariants();renderSleepbagVariantControl();}
sleepbagVariantPanel.querySelector('.set-variant-close').onclick=()=>closeSleepbagVariants(true);sleepbagVariantPanel.querySelector('.set-variant-done').onclick=()=>closeSleepbagVariants(true);
document.addEventListener('click',e=>{const product=e.target.closest('[data-product]');if(product&&!state.busy){if(product.dataset.product==='sleepbag'){if(sleepbagVariantPanel.hidden)openSleepbagVariants();else closeSleepbagVariants()}else closeSleepbagVariants();renderSleepbagVariantControl();return;}if(e.target.closest('#resetBtn')&&!state.busy)state.sleepbagVariant='travel';if(!sleepbagVariantPanel.contains(e.target))closeSleepbagVariants();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!sleepbagVariantPanel.hidden)closeSleepbagVariants(true);if(e.key==='ArrowDown'&&e.target.closest('[data-product="sleepbag"]')&&!state.busy){e.preventDefault();openSleepbagVariants();sleepbagVariantPanel.querySelector('[aria-pressed=true]')?.focus();}});
window.addEventListener('resize',()=>closeSleepbagVariants());window.addEventListener('scroll',e=>{if(!sleepbagVariantPanel.contains(e.target))closeSleepbagVariants()},{passive:true,capture:true});
new MutationObserver(renderSleepbagVariantControl).observe($('products'),{childList:true});new MutationObserver(()=>{if(state.busy)closeSleepbagVariants();renderSleepbagVariantControl()}).observe($('generateBtn'),{attributes:true,attributeFilter:['disabled']});renderSleepbagVariantControl();
